"""ESPHome Light: emulator (generated by `openbridge partner new`). It speaks the same three-method transport as the
real device, so the adapter, the tests and demos run before the hardware arrives. Make it faithful: copy the
device's real value ranges, delays and quirks here as you learn them."""
import copy


class EsphomeLightEmulator:
    def __init__(self, **state):
        self.state = {'power': 'off', 'brightness': 50, 'firmware': '2026.11.0-emulated'}
        self.state.update(state)
        self.history = []          # every write and command, for tests and demos
        self.drop_writes = False   # simulate a device that acknowledges but does not change

    def read(self):
        return copy.deepcopy(self.state)

    def write(self, name, value):
        self.history.append(('write', name, value))
        if not self.drop_writes:
            self.state[name] = value
            if name == 'brightness' and value:
                self.state['power'] = 'on'     # like the real API: setting brightness lights up

    def command(self, name, value=None):
        self.history.append(('command', name, value))
        if name == 'toggle' and not self.drop_writes:
            self.state['power'] = 'off' if self.state.get('power') == 'on' else 'on'


if __name__ == '__main__':
    emu = EsphomeLightEmulator()
    print('ESPHome Light emulator state:', emu.read())
